package de.lazytv.pro.catalog;
import java.io.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class M3uParserTest {
 private Catalog parse(String body)throws Exception{return M3uParser.parse(new BufferedReader(new StringReader(body)));}
 @Test public void quotedAttributesAndCommaInTitle()throws Exception{Catalog catalog=parse("\uFEFF#EXTM3U\n#EXTINF:-1 tvg-id=\"news.al\" tvg-logo=\"https://cdn/logo.png\" group-title=\"AL, News\",News, HD\nhttps://host/live/1.ts\n");StreamItem item=catalog.items.get(0);assertEquals("News, HD",item.name);assertEquals("news.al",item.tvgId);assertEquals("https://cdn/logo.png",item.logo);assertEquals("AL, News",catalog.categories.get(0).name);}
 @Test public void extgrpAndPerStreamHeadersDoNotLeak()throws Exception{Catalog catalog=parse("#EXTM3U\n#EXTINF:-1,First\n#EXTGRP:Documentary\n#EXTVLCOPT:http-user-agent=ProviderClient\n#EXTHTTP:{\"Cookie\":\"fixture=value\"}\nhttps://host/first.ts|Referer=https%3A%2F%2Fportal%2F\n#EXTINF:-1,Second\nhttps://host/second.ts\n");M3uStreamItem first=(M3uStreamItem)catalog.items.get(0),second=(M3uStreamItem)catalog.items.get(1);assertEquals("Documentary",catalog.categories.get(0).name);assertEquals("ProviderClient",first.requestHeaders.get("User-Agent"));assertEquals("fixture=value",first.requestHeaders.get("Cookie"));assertEquals("https://portal/",first.requestHeaders.get("Referer"));assertTrue(second.requestHeaders.isEmpty());}
 @Test public void seriesContainerCarriesEpisodesForLocalAndRemote()throws Exception{Catalog catalog=parse("#EXTM3U\n#EXTINF:-1 group-title=\"Series\" plot=\"Provider plot\",Example S01E02\n#EXTVLCOPT:http-user-agent=EpisodeClient\nhttps://host/e2.mp4\n#EXTINF:-1 group-title=\"Series\",Example S01E01\nhttps://host/e1.mp4\n");assertEquals(1,catalog.items.size());M3uSeries series=(M3uSeries)catalog.items.get(0);assertEquals("Example",series.name);assertTrue(series.streamUrl.isEmpty());SeriesDetails details=series.details();assertEquals(1,details.seasons.size());assertEquals(2,details.episodes.get(1).size());assertEquals(1,details.episodes.get(1).get(0).episodeNumber);Episode second=details.episodes.get(1).get(1);assertEquals("Provider plot",second.meta("plot"));assertEquals("EpisodeClient",((M3uHeaders)second).requestHeaders().get("User-Agent"));}
 @Test public void unknownEpisodeNumbersAreNotInvented()throws Exception{Catalog catalog=parse("#EXTM3U\n#EXTINF:-1 content-type=\"series\" series-name=\"Provider Series\",Pilot\nhttps://host/video.mp4\n");Episode episode=((M3uSeries)catalog.items.get(0)).details().episodes.get(0).get(0);assertEquals(0,episode.seasonNumber);assertEquals(0,episode.episodeNumber);}
 @Test public void movieMetadataAndLegacyLiveIdentityArePreserved()throws Exception{Catalog catalog=parse("#EXTM3U\n#EXTINF:-1 group-title=\"Movies\" year=\"2024\" rating=\"8.2\",Movie\nhttps://host/movie.mp4\n#EXTINF:-1 group-title=\"General\",Channel\nhttps://host/channel.ts\n");assertEquals(CatalogType.MOVIES,catalog.items.get(0).type);assertEquals("2024",catalog.items.get(0).meta("year"));assertEquals("m3u-"+Integer.toHexString(("Channel"+"https://host/channel.ts").hashCode()),catalog.items.get(1).id);}
}
